__device__ __forceinline__ void load_b(TileB& b,const float* p) {
    const float* src=p+(threadIdx.x%8)*STRIDE+((threadIdx.x/8)*4)%8;
    asm volatile("ldmatrix.sync.aligned.m8n8.x2.b16 {%0,%1}, [%2];"
        : "=r"(b.x[0]),"=r"(b.x[1]):"l"(src));
